+void ColorPickerShapeRectangle::_hue_slider_draw(int64_t p_shape) {
+	ColorPickerShapeRectangle *shape = reinterpret_cast<ColorPickerShapeRectangle *>(p_shape);
+	Control *hue_slider = shape->hue_slider;
